#ifndef STM32F401xE
#define STM32F401xE
#endif

#include "stm32f4xx.h"
#include "oled_ssd1306.h"
#include "sensor_flex.h"
#include "bluetooth.h"
#include "motor.h"

#include <stdlib.h>    // Necesario para atoi()
#include <string.h>    // Necesario para strncmp()

int main(void) {
    // 1. Activar coprocesador FPU para matemáticas
    SCB->CPACR |= ((3UL << 10*2) | (3UL << 11*2));

    // 2. Inicializar periféricos
    OLED_Init();
    OLED_Clear();
    ADC1_PA0_Init();
    Bluetooth_Init();

    // 3. Inicializar el Control PID del motor y fijar posición en 0
    Motor_Init();
    Motor_SetTargetAngle(0.0f);

    // 4. Imprimir la interfaz estática inicial en la OLED
    OLED_PrintStr("PROTESIS BIONICA", 0, 16);
    OLED_PrintStr("FLEXION:", 2, 10);
    OLED_PrintStr("%", 2, 80);
    OLED_PrintStr("ESTADO:", 4, 10);
    OLED_PrintStr("DESACTIVADO", 5, 25);
    OLED_PrintStr("RX:", 6, 10);
    OLED_PrintStr("RAW ADC:", 7, 10);

    uint16_t valor_adc = 0;
    uint8_t porcentaje = 0;

    // Variables de control y gatillo
    uint8_t estado_protesis = 0;    // 0 = Abierta, 1 = Cerrada
    uint8_t listo_para_cambio = 1;  // Evita el rebote de la señal
    uint8_t limite_activacion = 50; // Umbral de flexión (modificable por BT)

    char comando_bt[BT_BUFFER_SIZE];

    // --- ESTABILIZACIÓN DEL BLUETOOTH ---
    // Retraso para evitar que el HC-05 envíe "basura" al iniciar
    for (volatile int i = 0; i < 1000000; i++);

    // Mensaje de bienvenida al monitor serie / celular
    Bluetooth_SendString("\r\n--- PROTESIS INICIADA ---\r\n");
    Bluetooth_SendString("Escribe 'limite XX' para cambiar umbral.\r\n");

    while (1) {

        // --- 1. ATENDER BLUETOOTH ---
        if (Bluetooth_HasCommand()) {
            Bluetooth_GetCommand(comando_bt);

            OLED_PrintStr("             ", 6, 35);
            OLED_PrintStr(comando_bt, 6, 35);

            if (strncmp(comando_bt, "limite", 6) == 0 || strncmp(comando_bt, "Limite", 6) == 0) {
                uint8_t nuevo_limite = (uint8_t)atoi(&comando_bt[6]);

                if (nuevo_limite > 20 && nuevo_limite <= 100) {
                    limite_activacion = nuevo_limite;
                    Bluetooth_SendString("Exito: Umbral cambiado a ");
                    Bluetooth_SendNum(limite_activacion);
                    Bluetooth_SendString("%\r\n");
                } else {
                    Bluetooth_SendString("Error: El limite debe estar entre 21 y 100\r\n");
                }
            } else {
                Bluetooth_SendString("Comando no reconocido.\r\n");
            }
        }

        // --- 2. LEER SENSOR DE FLEXIÓN ---
        valor_adc = ADC1_Read();
        porcentaje = CalcularPorcentajeFlexion(valor_adc);

        // --- 3. ACTUALIZAR PANTALLA (Porcentaje) ---
        OLED_PrintNum(porcentaje, 2, 62);
        if (porcentaje < 10) {
            OLED_PrintStr("  ", 2, 68);
        } else if (porcentaje < 100) {
            OLED_PrintStr(" ", 2, 74);
        }

        // --- 4. LÓGICA DE ESTADO Y CONTROL DE MOTOR ---
        if (porcentaje > limite_activacion && listo_para_cambio == 1) {
            if (estado_protesis == 0) {
                // Activar prótesis (Cerrar mano)
                estado_protesis = 1;
                OLED_PrintStr("           ", 5, 25);
                OLED_PrintStr("ACTIVADO", 5, 25);

                // Manda el motor a la posición de cierre
                Motor_SetTargetAngle(90.0f);
            } else {
                // Desactivar prótesis (Abrir mano)
                estado_protesis = 0;
                OLED_PrintStr("           ", 5, 25);
                OLED_PrintStr("DESACTIVADO", 5, 25);

                // Regresa el motor a la posición inicial
                Motor_SetTargetAngle(0.0f);
            }
            listo_para_cambio = 0; // Bloquea hasta que el usuario relaje la mano
        }
        else if (porcentaje < 20) {
            listo_para_cambio = 1; // Rearma el mecanismo al bajar del 20%
        }

        // --- 5. ACTUALIZAR PANTALLA (RAW ADC) ---
        OLED_PrintNum(valor_adc, 7, 62);
        if (valor_adc < 10) {
            OLED_PrintStr("   ", 7, 68);
        } else if (valor_adc < 100) {
            OLED_PrintStr("  ", 7, 74);
        } else if (valor_adc < 1000) {
            OLED_PrintStr(" ", 7, 80);
        }

        // Retardo para no saturar la pantalla OLED
        for (volatile int i = 0; i < 300000; i++);
    }
}
